#include "v42_arq.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>

static size_t take(struct v42_arq*a,uint8_t*b){size_t n=v42_arq_next(a,b,V42_HDLC_MAX_BITS);assert(n);return n;}
int main(void){struct v42_arq a,b;v42_arq_init(&a,1);v42_arq_init(&b,0);uint8_t source[300],got[400]={0},f0[V42_HDLC_MAX_BITS],f1[V42_HDLC_MAX_BITS],f2[V42_HDLC_MAX_BITS],reply[V42_HDLC_MAX_BITS];for(size_t i=0;i<sizeof source;i++)source[i]=(uint8_t)i;assert(v42_arq_write(&a,source,sizeof source)==sizeof source);size_t n0=take(&a,f0),n1=take(&a,f1),n2=take(&a,f2);assert(v42_arq_receive(&b,f0,n0)==1);f1[n1/2]^=1;assert(v42_arq_receive(&b,f1,n1)<0);assert(v42_arq_receive(&b,f2,n2)==0);size_t nr=take(&b,reply);struct v42_lapm_frame r;assert(v42_lapm_decode(reply,nr,&r)==0&&r.type==V42_LAPM_REJ&&r.nr==1);assert(v42_arq_receive(&a,reply,nr)==0);n1=take(&a,f1);n2=take(&a,f2);assert(v42_arq_receive(&b,f1,n1)==1);assert(v42_arq_receive(&b,f2,n2)==1);nr=take(&b,reply);assert(v42_arq_receive(&a,reply,nr)==0&&v42_arq_unacked(&a)==0);size_t z=v42_arq_read(&b,got,sizeof got);assert(z==sizeof source&&!memcmp(got,source,z));v42_arq_init(&a,1);v42_arq_init(&b,0);a.va=a.vs=a.send_cursor=b.vr=126;assert(v42_arq_write(&a,source,sizeof source)==sizeof source);for(int i=0;i<3;i++){n0=take(&a,f0);assert(v42_arq_receive(&b,f0,n0)==1);}nr=take(&b,reply);assert(v42_arq_receive(&a,reply,nr)==0&&a.va==1&&v42_arq_unacked(&a)==0);v42_arq_init(&a,1);v42_arq_init(&b,0);assert(v42_arq_write(&a,source,32)==32);n0=take(&a,f0);v42_arq_advance(&a,1000);n1=take(&a,f1);assert(v42_arq_receive(&b,f1,n1)==1);nr=take(&b,reply);assert(v42_arq_receive(&a,reply,nr)==0&&!v42_arq_unacked(&a));assert(v42_arq_receive(&b,f1,n1)==0);nr=take(&b,reply);assert(v42_lapm_decode(reply,nr,&r)==0&&r.type==V42_LAPM_RR);puts("V.42 LAPM ARQ: REJ, wrap, T401 retry and duplicate RR pass");return 0;}
